package main

import (
	"bytes"
	"fmt"
	"go/format"
	"strconv"
	"text/template"
)

const header = "Code generated by tools/brandgen from brand/brand.json. DO NOT EDIT."

// Output is one generated file, addressed relative to the repository root.
type Output struct {
	Path    string
	Content []byte
}

// Render produces every generated file for a brand. Paths are fixed: other
// code imports them, so moving one is a contract change.
func Render(b Brand) ([]Output, error) {
	goSrc, err := renderGo(b)
	if err != nil {
		return nil, err
	}
	tsSrc, err := renderTemplate(tsTemplate, b)
	if err != nil {
		return nil, err
	}
	envSrc, err := renderTemplate(envTemplate, b)
	if err != nil {
		return nil, err
	}
	return []Output{
		{Path: "go/gen/brand/brand_gen.go", Content: goSrc},
		{Path: "packages/brand/src/index.ts", Content: tsSrc},
		{Path: "installer/brand.env", Content: envSrc},
	}, nil
}

func renderGo(b Brand) ([]byte, error) {
	raw, err := renderTemplate(goTemplate, b)
	if err != nil {
		return nil, err
	}
	formatted, err := format.Source(raw)
	if err != nil {
		return nil, fmt.Errorf("gofmt generated brand: %w", err)
	}
	return formatted, nil
}

type templateData struct {
	Header            string
	PlaceholderPrefix string
	Fields            []field
}

func renderTemplate(t *template.Template, b Brand) ([]byte, error) {
	var buf bytes.Buffer
	data := templateData{Header: header, PlaceholderPrefix: PlaceholderPrefix, Fields: b.fields()}
	if err := t.Execute(&buf, data); err != nil {
		return nil, fmt.Errorf("render %s: %w", t.Name(), err)
	}
	return buf.Bytes(), nil
}

// Values are validated to contain no quotes, backslashes or newlines, so
// strconv.Quote yields a literal that is valid in both Go and TypeScript and
// plain single quotes are safe in the shell file.
var funcs = template.FuncMap{"quote": strconv.Quote}

var goTemplate = template.Must(template.New("brand_gen.go").Funcs(funcs).Parse(`// {{.Header}}

// Package brand holds the product identity. Every name, path and URL that
// would change in a rename comes from here, never from a string literal.
package brand

// PlaceholderPrefix marks values that are not set yet.
const PlaceholderPrefix = {{quote .PlaceholderPrefix}}

const (
{{- range .Fields}}
	// {{.Doc}}
	{{.Go}} = {{quote .Value}}
{{- end}}
)
`))

var tsTemplate = template.Must(template.New("index.ts").Funcs(funcs).Parse(`// {{.Header}}

/** Marks values that are not set yet. */
export const placeholderPrefix = {{quote .PlaceholderPrefix}};
{{range .Fields}}
/** {{.Doc}} */
export const {{.TS}} = {{quote .Value}};
{{end}}
export const brand = {
{{- range .Fields}}
  {{.TS}},
{{- end}}
} as const;

export type Brand = typeof brand;

/** True when a brand value is still a placeholder. */
export function isPlaceholder(value: string): boolean {
  return value.startsWith(placeholderPrefix);
}
`))

var envTemplate = template.Must(template.New("brand.env").Parse(`# {{.Header}}
# Sourced by install.sh. Values never contain quotes, so single quotes are safe.
BRAND_PLACEHOLDER_PREFIX='{{.PlaceholderPrefix}}'
{{- range .Fields}}
{{.Env}}='{{.Value}}'
{{- end}}
`))
